import { useLoadingMessage, useCurrentLanguage } from "../utils/store";

export default function Loading() {
	const loadingMessage = useLoadingMessage();
	const t = useCurrentLanguage()

	return (
		<div className="container flex-grow-1 d-flex align-items-center justify-content-center py-5">
			<div className="card bg-dark text-light border-secondary shadow-lg w-100 text-center" style={{ maxWidth: '400px' }}>
				<div className="card-body p-5 d-flex flex-column align-items-center justify-content-center">
					<div className="spinner-border text-primary mb-4" role="status" style={{ width: '3rem', height: '3rem' }}>
						<span className="visually-hidden">{t.loading_default}</span>
					</div>
					<h3 className="h5 fw-semibold mb-0">{loadingMessage || t.loading_default}</h3>
				</div>
			</div>
		</div>
	);
}
