import { useCsv, useRaportConfig, useCurrentLanguage, useStoreActions } from "../utils/store.js";

const ChartItem = ({ chart, chartIndex, headers, updateChart, removeChart, t }) => (
	<div className="card bg-dark border-secondary p-3 mb-3">
		<div className="mb-3">
			<label htmlFor={`chartTitle-${chart.id}`} className="form-label text-secondary small text-uppercase fw-semibold">{t.chart_builder_title}</label>
			<input
				id={`chartTitle-${chart.id}`}
				type="text"
				name="chartTitle"
				className="form-control bg-dark text-light border-secondary"
				value={chart.title}
				onChange={(e) => updateChart(chartIndex, 'title', e.target.value)}
			/>
		</div>
		<div className="mb-3">
			<label htmlFor={`axisX-${chart.id}`} className="form-label text-secondary small text-uppercase fw-semibold">{t.chart_builder_x}</label>
			<select
				id={`axisX-${chart.id}`}
				name="axisX"
				className="form-select bg-dark text-light border-secondary"
				value={chart.axisX}
				onChange={(e) => updateChart(chartIndex, 'axisX', e.target.value)}
			>
				{headers.map((header) => (<option key={`${header}X`} value={header}>{header}</option>))}
			</select>
		</div>
		<div className="mb-3">
			<label htmlFor={`axisY-${chart.id}`} className="form-label text-secondary small text-uppercase fw-semibold">{t.chart_builder_y}</label>
			<select
				id={`axisY-${chart.id}`}
				name="axisY"
				className="form-select bg-dark text-light border-secondary"
				value={chart.axisY}
				onChange={(e) => updateChart(chartIndex, 'axisY', e.target.value)}
			>
				{headers.map((header) => (<option key={`${header}Y`} value={header}>{header}</option>))}
			</select>
		</div>
		<div className="mb-3 d-flex flex-column gap-2">
			<div className="form-check">
				<input
					type="checkbox"
					id={`regression-${chart.id}`}
					name="regression"
					className="form-check-input bg-dark border-secondary"
					checked={chart.regression}
					onChange={(e) => { updateChart(chartIndex, 'regression', e.target.checked) }}
				/>
				<label htmlFor={`regression-${chart.id}`} className="form-check-label text-light">{t.chart_builder_regression}</label>
			</div>

			<div className="form-check">
				<input
					type="checkbox"
					id={`determination-${chart.id}`}
					name="determination"
					className="form-check-input bg-dark border-secondary"
					checked={chart.determination}
					onChange={(e) => { updateChart(chartIndex, 'determination', e.target.checked) }}
				/>
				<label htmlFor={`determination-${chart.id}`} className="form-check-label text-light">{t.chart_builder_determination}</label>
			</div>
		</div>
		<div className="d-flex justify-content-end">
			<button className="btn btn-outline-danger btn-sm" onClick={() => removeChart(chartIndex)}>{t.chart_builder_delete_btn}</button>
		</div>
	</div>
);

export default function Configure() {
	const csv = useCsv();
	const raportConfig = useRaportConfig();
	const {
		nextPage,
		addChart,
		removeChart,
		setRaportTitle,
		updateChart,
		toggleData,
		toggleRowData,
		toggleStatData,
		isChecked,
		resetConfigure
	} = useStoreActions();
	const t = useCurrentLanguage();

	const headers = csv?.meta?.fields || [];
	const statTypes = ['mean', 'median', 'deviation', 'error', 'range', 'uncertainty'];

	return (
		<div className="container flex-grow-1 d-flex align-items-center justify-content-center py-5">
			<div className="card bg-dark text-light border-secondary shadow-lg w-100" style={{ maxWidth: '900px' }}>
				<div className="card-body p-4">
					<h2 className="card-title h3 mb-4 fw-bold border-bottom border-secondary pb-2">{t.configue_title}</h2>

					<div className="mb-4">
						<label htmlFor="raportTitle" className="form-label text-secondary small text-uppercase fw-semibold">{t.configure_raport_title}</label>
						<input
							type="text"
							id="raportTitle"
							name="raportTitle"
							placeholder={t.configure_raport_title_placeholder}
							className="form-control bg-dark text-light border-secondary"
							value={raportConfig.title}
							onChange={(e) => setRaportTitle(e.target.value)}
						/>
					</div>

					<h3 className="h5 text-secondary mb-3">{t.configure_statistics}</h3>
					<div className="table-responsive mb-4">
						<table
							className="table table-dark table-bordered table-hover align-middle border-secondary w-100"
							style={{ tableLayout: 'fixed' }}
						>
							<thead>
								<tr>
									<th scope="col" style={{ width: '22%' }} className="align-middle text-wrap p-2">
										{t.configure_table_column}
									</th>
									{statTypes.map((stat) => (
										<th
											key={stat}
											scope="col"
											style={{ width: '13%', cursor: 'pointer' }}
											className="text-center align-middle text-wrap p-2 user-select-none"
											onClick={() => toggleStatData(stat, headers)}
											title="Kliknij, aby zaznaczyć/odznaczyć dla wszystkich kolumn"
										>
											{t[stat]}
										</th>
									))}
								</tr>
							</thead>
							<tbody>
								{headers.map((header) => (
									<tr key={`header-${header}`}>
										<td
											className="align-middle fw-semibold text-break p-2 user-select-none"
											style={{ cursor: 'pointer' }}
											onClick={() => toggleRowData(header, statTypes)}
											title="Kliknij, aby zaznaczyć/odznaczyć wszystkie statystyki dla tej kolumny"
										>
											{header}
										</td>

										{statTypes.map((statType) => (
											<td key={`${header}-${statType}`} className="text-center align-middle p-0">
												<label
													className="d-flex align-items-center justify-content-center w-100 h-100 m-0"
													style={{ cursor: 'pointer', minHeight: '45px' }}
												>
													<input
														type="checkbox"
														className="form-check-input bg-dark border-secondary m-0"
														style={{ transform: 'scale(1.4)', cursor: 'pointer' }}
														checked={isChecked(header, statType)}
														onChange={() => toggleData(header, statType)}
													/>
												</label>
											</td>
										))}
									</tr>
								))}
							</tbody>
						</table>
					</div>

					<h3 className="h5 text-secondary mb-3">{t.configure_charts}</h3>
					<div className="mb-3">
						<button className="btn btn-outline-light btn-sm" onClick={() => addChart(headers[0], headers[0])}>{t.configure_add_chart_btn}</button>
					</div>

					<div id="charts" className="mb-4">
						{raportConfig.charts.map((chart, index) => (
							<ChartItem
								key={chart.id}
								chart={chart}
								chartIndex={index}
								headers={headers}
								updateChart={updateChart}
								removeChart={removeChart}
								t={t}
							/>
						))}
					</div>

					<div className="d-flex justify-content-end border-top border-secondary pt-3">
						<button className="btn btn-danger m-3 px-4 fw-semibold" onClick={resetConfigure}>{t.configure_reset_btn}</button>
						<button className="btn btn-primary m-3 px-4 fw-semibold" onClick={nextPage}>{t.configure_next_page_btn}</button>
					</div>
				</div>
			</div>
		</div>
	);
}
