import { create } from 'zustand';
import { useShallow } from 'zustand/react/shallow';
import en from "../languages/en.js";
import pl from "../languages/pl.js";

export const useStore = create((set, get) => ({
	page: 0,
	file: null,
	csv: null,
	previousPage: null,
	raportConfig: {
		title: "",
		data: [],
		charts: [],
	},
	loadingMessage: "",
	languages: { en, pl },
	currentLanguage: "en",

	// Akcje
	setLanguage: (newLanguage) => set((state) => ({ currentLanguage: newLanguage })),
	setRaportTitle: (title) => set((state) => ({ raportConfig: { ...state.raportConfig, title: title } })),
	addChart: (defaultX = "", defaultY = "") => set((state) => {
		const headers = state.csv?.meta?.fields || [];
		const fallbackX = defaultX || headers[0] || "";
		const fallbackY = defaultY || headers[0] || "";

		return {
			raportConfig: {
				...state.raportConfig,
				charts: [
					...state.raportConfig.charts,
					{
						id: Date.now() + Math.random(),
						title: "",
						axisX: fallbackX,
						axisY: fallbackY,
						regression: false,
						determination: false,
					}
				]
			}
		};
	}),
	updateChart: (index, field, value) => set((state) => {
		const updatedCharts = [...state.raportConfig.charts];
		updatedCharts[index] = { ...updatedCharts[index], [field]: value };
		return { raportConfig: { ...state.raportConfig, charts: updatedCharts } };
	}),
	removeChart: (index) => set((state) => ({
		raportConfig: { ...state.raportConfig, charts: state.raportConfig.charts.filter((_, i) => i !== index) }
	})),

	toggleData: (column, data) => set((state) => {
		const currentData = state.raportConfig.data;
		const exists = currentData.some((element) => element.column === column && element.data === data);
		let newData;
		if (exists) {
			newData = currentData.filter((element) => !(element.column === column && element.data === data));
		} else {
			newData = [...currentData, { column, data }];
		}
		return {
			raportConfig: { ...state.raportConfig, data: newData }
		};
	}),

	toggleRowData: (column, statTypes) => set((state) => {
		const currentData = state.raportConfig.data;
		const allSelected = statTypes.every(stat =>
			currentData.some(item => item.column === column && item.data === stat)
		);

		let newData;
		if (allSelected) {
			newData = currentData.filter(item => !(item.column === column && statTypes.includes(item.data)));
		} else {
			const missing = statTypes
				.filter(stat => !currentData.some(item => item.column === column && item.data === stat))
				.map(stat => ({ column, data: stat }));
			newData = [...currentData, ...missing];
		}

		return { raportConfig: { ...state.raportConfig, data: newData } };
	}),

	toggleStatData: (statType, headers) => set((state) => {
		const currentData = state.raportConfig.data;
		const allSelected = headers.every(header =>
			currentData.some(item => item.column === header && item.data === statType)
		);

		let newData;
		if (allSelected) {
			newData = currentData.filter(item => !(headers.includes(item.column) && item.data === statType));
		} else {
			const missing = headers
				.filter(header => !currentData.some(item => item.column === header && item.data === statType))
				.map(header => ({ column: header, data: statType }));
			newData = [...currentData, ...missing];
		}

		return { raportConfig: { ...state.raportConfig, data: newData } };
	}),

	isChecked: (column, data) => get().raportConfig.data.some(item => item.column === column && item.data === data),
	nextPage: () => set((state) => ({ previousPage: state.page, page: (state.page + 1) % 3 })),
	goToPreviousPage: () => set((state) => {
		if (state.page === 0 || state.page === 3) return {};
		return { page: state.page - 1 };
	}),
	setFile: (file) => set({ file: file }),
	setCsv: (csv) => set({ csv: csv }),
	resetApp: () => set({ page: 0, file: null, csv: null, previousPage: null }),
	resetConfigure: () => set({
		raportConfig: {
			title: "",
			data: [],
			charts: [],
		},
	}),

	// --- POPRAWIONA AKCJA SWITCHLOADING ---
	switchLoading: (on, message = "") => set((state) => {
		if (on) {
			return {
				// Zapamiętujemy poprzednią stronę tylko jeśli wchodzimy na ekran ładowania po raz pierwszy
				previousPage: state.page !== 3 ? state.page : state.previousPage,
				page: 3,
				loadingMessage: message
			};
		} else {
			return {
				page: state.previousPage ?? 0
			};
		}
	})
}));

// --- SELEKTORY ZUSTAND ---
export const usePage = () => useStore((state) => state.page);
export const useFile = () => useStore((state) => state.file);
export const useCsv = () => useStore((state) => state.csv);
export const useRaportConfig = () => useStore((state) => state.raportConfig);
export const useLoadingMessage = () => useStore((state) => state.loadingMessage);
export const useLanguages = () => useStore((state) => state.languages);
export const useCurrentLanguage = () => useStore((state) => state.languages[state.currentLanguage]);
export const useCurrentLanguageCode = () => useStore((state) => state.currentLanguage);

export const useStoreActions = () => useStore(
	useShallow((state) => ({
		setRaportTitle: state.setRaportTitle,
		addChart: state.addChart,
		updateChart: state.updateChart,
		removeChart: state.removeChart,
		toggleData: state.toggleData,
		toggleRowData: state.toggleRowData,
		toggleStatData: state.toggleStatData,
		isChecked: state.isChecked,
		nextPage: state.nextPage,
		goToPreviousPage: state.goToPreviousPage,
		setFile: state.setFile,
		setCsv: state.setCsv,
		resetConfigure: state.resetConfigure,
		resetApp: state.resetApp,
		switchLoading: state.switchLoading,
		setLanguage: state.setLanguage
	}))
);
