import * as ss from 'simple-statistics'

const standardError = (data) => {
	if (!data || data.length === 0) return 0;
	return ss.sampleStandardDeviation(data) / Math.sqrt(data.length);
};

export const Statistics = (data, mode) => {
	switch (mode) {
		case 'mean': return ss.mean(data)
		case 'median': return ss.median(data)
		case 'deviation': return ss.sampleStandardDeviation(data)
		case 'error': return standardError(data)
		case 'range': const [min, max] = ss.extent(data); return max - min
		case 'uncertainty': return (standardError(data) / ss.mean(data)) * 100
	}
}
