import { useFile, useStoreActions, useCurrentLanguage } from "../utils/store";
import Papa from 'papaparse';

export default function Upload() {
	const file = useFile();
	const t = useCurrentLanguage()
	const { setFile, setCsv, switchLoading, nextPage } = useStoreActions();

	const handleSubmit = (event) => {
		event.preventDefault();
		if (!file) return;

		switchLoading(true, t.loading_uploading_file);

		Papa.parse(file, {
			header: true,
			skipEmptyLines: 'greedy',
			dynamicTyping: true,
			transformHeader: (header) => header.trim(),
			transform: (value) => {
				if (typeof value === 'string') {
					const trimmed = value.trim();
					return trimmed === '' ? null : trimmed;
				}
				return value;
			},
			complete: (parsed) => {
				if (parsed.meta?.fields) {
					parsed.meta.fields = parsed.meta.fields
						.map((f) => f.trim())
						.filter(Boolean);
				}
				setCsv(parsed);
				switchLoading(false);
				nextPage();
			},
			error: (error) => {
				console.error(t.error_parsing, error);
				switchLoading(false);
			}
		});
	};

	const handleChange = (event) => {
		if (event.target.files && event.target.files[0]) {
			setFile(event.target.files[0]);
		}
	};

	return (
		<div className="container flex-grow-1 d-flex align-items-center justify-content-center py-5">
			<div className="card bg-dark text-light border-secondary shadow-lg w-100" style={{ maxWidth: '600px' }}>
				<div className="card-body p-4">
					<h2 className="card-title h3 mb-4 fw-bold border-bottom border-secondary pb-2">{t.upload_title}</h2>

					<form onSubmit={handleSubmit}>
						<div className="mb-3">
							<label htmlFor="file" className="form-label text-secondary small text-uppercase fw-semibold">{t.upload_file_label}</label>
							<input
								type="file"
								name="file"
								accept=".csv"
								className="form-control bg-dark text-light border-secondary"
								onChange={handleChange}
							/>
						</div>
						<div className="d-flex justify-content-end mt-4">
							<button type="submit" className="btn btn-primary px-4 fw-semibold" disabled={!file}>
								{t.upload_upload_btn}
							</button>
						</div>
					</form>
				</div>
			</div>
		</div>
	);
}
