import { usePage, useCurrentLanguage, useCurrentLanguageCode, useLanguages, useStoreActions } from "./utils/store"
import { pages } from "./utils/pages"
import Page404 from "./pages/404"

const App = () => {
	const page = usePage();
	const languages = useLanguages()
	const t = useCurrentLanguage()
	const currentlanguageCode = useCurrentLanguageCode()
	const { goToPreviousPage, setLanguage } = useStoreActions();
	const Component = pages[page];

	return (
		<div className="bg-dark text-light vh-100 d-flex flex-column overflow-hidden">
			<header className="border-bottom border-secondary py-3 px-4 shadow-sm bg-dark flex-shrink-0">
				<div className="container-fluid d-flex align-items-center justify-content-between">
					{page > 0 ? (
						<button
							onClick={goToPreviousPage}
							className="btn btn-outline-secondary btn-sm"
						>
							&larr; {t.back_btn}
						</button>
					) : (
						<div />
					)}

					<div className="d-flex align-items-center gap-2">
						<span className="fs-4 fw-bold text-primary">{t.appTitle}</span>
					</div>
					<span className="badge bg-secondary text-uppercase fw-normal px-2 py-1">{t.version}</span>
				</div>
			</header>

			<main className="flex-grow-1 d-flex flex-column overflow-y-auto">
				{Component ? <Component /> : <Page404 />}
			</main>

			<footer className="border-top border-secondary py-3 px-4 bg-dark flex-shrink-0">
				<div className="container-fluid d-flex flex-column flex-sm-row align-items-center justify-content-between gap-2">
					<select onChange={(e) => setLanguage(e.target.value)} value={currentlanguageCode} className="form-select form-select-sm w-auto bg-dark text-light border-secondary">
						{Object.keys(languages).map((language) => (<option key={language} value={language}>{languages[language].emoji} {language.toUpperCase()}</option>))}
					</select>
					<span className="text-secondary small">
						{t.footer}
					</span>
				</div>
			</footer>
		</div>
	)
}

export default App;
