import { useCsv, useRaportConfig, useCurrentLanguage, useStoreActions } from "../utils/store";
import { Statistics } from "../utils/statistics";
import htmlTemplateString from '../templates/template.html';
import html2pdf from "html2pdf.js";
import { linearRegression, linearRegressionLine, rSquared } from 'simple-statistics';
import { Chart, registerables } from "chart.js";

Chart.register(...registerables);

const escapeHtml = (str) => {
	if (!str) return '';
	return String(str)
		.replace(/&/g, "&amp;")
		.replace(/</g, "&lt;")
		.replace(/>/g, "&gt;")
		.replace(/"/g, "&quot;")
		.replace(/'/g, "&#039;");
};

const yieldThread = (ms = 50) => new Promise((resolve) => setTimeout(resolve, ms));

export default function Export() {
	const csv = useCsv();
	const raportConfig = useRaportConfig();
	const t = useCurrentLanguage();
	const { switchLoading } = useStoreActions();

	const handleSubmit = async (e) => {
		e.preventDefault();

		try {
			switchLoading(true, t.loading_title);
			await yieldThread();

			const template = new DOMParser().parseFromString(htmlTemplateString, 'text/html');
			const raportTitle = raportConfig.title || t.raport_default_title;

			const titleHeader = template.querySelector("#title");
			if (titleHeader) titleHeader.innerText = raportTitle;

			const titleElement = template.querySelector("title");
			if (titleElement) titleElement.innerText = raportTitle;

			switchLoading(true, t.loading_calculate_data);
			await yieldThread();

			const dataElement = template.querySelector("#data");
			if (dataElement) {
				dataElement.innerHTML = "";
				raportConfig.data.forEach(element => {
					const columnData = csv?.data
						? csv.data
							.map(row => {
								const val = row[element.column];
								if (val === null || val === undefined) return NaN;
								return typeof val === 'number' ? val : Number(String(val).trim());
							})
							.filter(val => typeof val === 'number' && !isNaN(val))
						: [];

					if (columnData.length === 0) {
						dataElement.innerHTML += `<p>${escapeHtml(element.column)} ${t[element.data]}: <strong>${t.raport_no_data}</strong></p>`;
					} else {
						try {
							const result = Statistics(columnData, element.data);
							const formattedResult = typeof result === 'number' ? result.toFixed(4) : result;
							dataElement.innerHTML += `<p>${escapeHtml(element.column)} <i>${t[element.data]}</i>: <strong>${formattedResult}</strong></p>`;
						} catch (error) {
							console.error(t.error_calculating, error);
							dataElement.innerHTML += `<p>${escapeHtml(element.column)} <i>${t[element.data]}</i>: <strong>Błąd obliczeń</strong></p>`;
						}
					}
				});
			}

			switchLoading(true, t.loading_generating_charts);
			await yieldThread();

			const chartsElement = template.querySelector("#charts");
			if (chartsElement) {
				chartsElement.innerHTML = "";
				for (const [index, chart] of raportConfig.charts.entries()) {
					const canvas = document.createElement("canvas");
					canvas.width = 800;
					canvas.height = 400;

					const points = csv?.data
						?.map(row => {
							const rawX = row[chart.axisX];
							const rawY = row[chart.axisY];
							const x = typeof rawX === 'number' ? rawX : Number(String(rawX).trim());
							const y = typeof rawY === 'number' ? rawY : Number(String(rawY).trim());
							return { x, y };
						})
						.filter(p => typeof p.x === 'number' && !isNaN(p.x) && typeof p.y === 'number' && !isNaN(p.y)) || [];

					const datasets = [{
						label: chart.title || `${chart.axisY} vs ${chart.axisX}`,
						data: points,
						backgroundColor: 'rgba(13, 110, 253, 1)',
						borderColor: 'rgba(13, 110, 253, 0.8)'
					}];

					let r2Text = "";

					if ((chart.regression || chart.determination) && points.length >= 2) {
						try {
							const ssFormatPoints = points.map(p => [p.x, p.y]);
							const lineModel = linearRegression(ssFormatPoints);
							const lineFunc = linearRegressionLine(lineModel);

							if (chart.regression) {
								const xValues = points.map(p => p.x);
								const minX = Math.min(...xValues);
								const maxX = Math.max(...xValues);

								datasets.push({
									type: 'line',
									label: `${t.regression}: y = ${lineModel.m.toFixed(2)}x + ${lineModel.b.toFixed(2)}`,
									data: [
										{ x: minX, y: lineFunc(minX) },
										{ x: maxX, y: lineFunc(maxX) }
									],
									borderColor: 'rgba(220, 53, 69, 1)',
									borderWidth: 2,
									pointRadius: 0,
									fill: false,
								});
							}

							if (chart.determination) {
								const r2 = rSquared(ssFormatPoints, lineFunc);
								r2Text = `${t.determination} = ${isNaN(r2) ? 'N/A' : r2.toFixed(4)}`;
							}
						} catch (err) {
							console.error(t.error_calculating, err);
						}
					}

					const chartInstance = new Chart(canvas, {
						type: 'scatter',
						data: { datasets },
						options: {
							responsive: false,
							animation: false,
							plugins: {
								subtitle: {
									display: Boolean(r2Text),
									text: r2Text,
									color: '#6c757d',
									font: { size: 14, style: 'italic' }
								}
							},
							scales: {
								x: { type: 'linear', title: { display: true, text: chart.axisX } },
								y: { type: 'linear', title: { display: true, text: chart.axisY } }
							}
						}
					});

					const imgUrl = canvas.toDataURL("image/png");
					chartInstance.destroy();

					const safeTitle = escapeHtml(chart.title || `${t.raport_default_chart} ${index + 1}`);
					chartsElement.innerHTML += `
						<div class="chart-card">
							<h3>${safeTitle}</h3>
							<img src="${imgUrl}" alt="${safeTitle}"/>
						</div>
					`;

					await yieldThread(10);
				}
			}

			switchLoading(true, t.loading_generating_file);
			await yieldThread();

			const opt = {
				margin: 10,
				filename: `${(raportConfig.title || t.raport_default_title).toLowerCase().replace(/\s+/g, '_')}.pdf`,
				image: { type: 'jpeg', quality: 0.98 },
				html2canvas: { scale: 2 },
				jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
			};

			await html2pdf().set(opt).from(template.documentElement.outerHTML).save();

		} catch (err) {
			console.error(t.error_generating_file, err);
		} finally {
			switchLoading(false);
		}
	};

	return (
		<div className="container flex-grow-1 d-flex align-items-center justify-content-center py-4">
			<div className="card bg-dark text-light border-secondary shadow-lg w-100" style={{ maxWidth: '600px' }}>
				<div className="card-body p-4">
					<h2 className="card-title h3 mb-4 fw-bold border-bottom border-secondary pb-2">{t.export_title}</h2>

					<form onSubmit={handleSubmit}>
						<div className="d-flex justify-content-center mt-4">
							<button type="submit" className="btn btn-primary px-4 fw-semibold">{t.export_export_btn}</button>
						</div>
					</form>
				</div>
			</div>
		</div>
	);
}
